INSERT INTO public.blog_posts (title, slug, category, author, excerpt, published, published_at, content) VALUES
('Hur många räcker en fruktkorg till? Storleksguide för kontoret','hur-manga-racker-en-fruktkorg','tips','Vitaminkorgen','Hur stor fruktkorg behöver ert kontor? Här är vår storleksguide från 4 kg till 11 kg – och tips för att varken få för lite eller för mycket frukt.',true,now(),
E'## Hur många räcker en fruktkorg till?\n\nDet vanligaste vi får frågan om är just detta: **hur många personer räcker en fruktkorg till?** Svaret beror på hur många som är på kontoret, hur ofta ni vill ha leverans och hur mycket frukt ni brukar äta. Här är en enkel guide.\n\n## Storleksguide för fruktkorg till kontoret\n\n| Antal medarbetare | Storlek per vecka | Tips |\n|---|---|---|\n| 5–8 | 4 kg | En korg per vecka räcker oftast |\n| 10–15 | 6 kg | Vanligast för mindre kontor |\n| 20–30 | 9 kg | Eller två mindre korgar på olika våningar |\n| 35–50 | 11 kg | Många väljer två leveransdagar i veckan |\n\nRäkna grovt med att varje person äter ett par frukter i veckan. Är ni fler än 50 hjälper vi er att ta fram en lösning som passar.\n\n## Så vet du om storleken är rätt\n\n- **Frukten tar slut redan på tisdagen?** Välj en större korg eller lägg till en extra leveransdag.\n- **Frukt blir kvar till fredag?** Välj en mindre storlek eller fler bananer och mindre ömtålig frukt.\n- **Många jobbar hemifrån vissa dagar?** Lägg leveransen på den dag flest är på plats.\n\nNi kan när som helst justera storlek och antal korgar – säg bara till.\n\n## Vilken fruktkorg ska vi välja?\n\nVi har tre korgar: **Original**, **Premium** och **Banan**. Original är en bra blandning för de flesta, Premium har mer variation och Banan passar er som vill ha mycket bananer. Korgarna finns från 140 kr.\n\n## Prova innan ni bestämmer er\n\nOsäker på storleken? Er första korg är gratis, så ni kan se hur mycket som går åt. Ni väljer själva startdatum och vi levererar när ni vill börja. Faktura kommer en gång i månaden.\n\n[Begär gratis offert](/kontakt) eller [se våra fruktkorgar](/produkter).'),
('Fruktleverans till kontoret – så fungerar det','fruktleverans-till-kontoret-sa-fungerar-det','tips','Vitaminkorgen','Så går en fruktleverans till kontoret till: från första kontakten och startdatum till veckoleverans och månadsfaktura.',true,now(),
E'## Fruktleverans till kontoret – så fungerar det\n\nEn **fruktleverans till kontoret** gör att ni har färsk frukt på jobbet varje vecka utan att någon behöver handla. Här går vi igenom hur det fungerar hos oss, steg för steg.\n\n## 1. Ni berättar vad ni behöver\n\nKontakta oss eller begär en gratis offert. Berätta hur många ni är och vilka dagar ni vill ha frukt. Offerten är gratis och ni binder er inte genom att fråga. Vi svarar inom 24 timmar.\n\n## 2. Ni väljer fruktkorg och storlek\n\nVälj mellan **Original**, **Premium** och **Banan**. Korgarna finns från 140 kr. Vill ni ha något mer kan vi även leverera fika, mejeri och skivad frukt.\n\n## 3. Ni väljer startdatum\n\nNi bestämmer själva när ni vill börja, och vi levererar direkt när ni vill starta. Er första korg är gratis.\n\n## 4. Vi levererar varje vecka\n\nVåra förare kommer på de dagar ni har valt. Vi kan ställa frukten och mjölken där ni vill ha den, till exempel i köket eller fikarummet. Behöver ni extra till ett möte eller en fika fixar vi det.\n\n## 5. En faktura i månaden\n\nNi får en samlad faktura en gång i månaden – inga dolda avgifter.\n\n## Varför välja fruktleverans?\n\n- **Sparar tid** – ingen på kontoret behöver handla eller bära.\n- **Alltid färskt** – frukten kommer varje vecka.\n- **Flexibelt** – ändra storlek, dagar eller lägg till extra när det behövs.\n\nVi levererar till företag i hela Stockholm. Läs mer om [fruktkorg i Stockholm](/fruktkorg-stockholm) eller [begär gratis offert](/kontakt). Ring oss gärna på [010-183 98 36](tel:0101839836).');